INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 14114, "", "", 14114081, 0, "vo_wac_14114_003", 0, "vo_wac_14114");
