INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 16614, 0, 0.5, 16614068, 1, "誕生、日……？\n私のですか？\nなぜそんなことを\n覚えているのですか？", 10, 102711);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 91, 16614, "", "", 16614069, "", "", "", 0);
