INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 16614, "", "", 16614072, 0, "vo_wac_16614_001", 0, "vo_wac_16614");
