INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 17614, "", "", 17614069, 0, "vo_wac_17614_001", 0, "vo_wac_17614");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 17614, 0, 0.5, 17614070, 1, "なんでって、今日はマコトはんの\nお誕生日やんか～？\nうちらと王子はんで、特製ケーキ、\n用意したんどすえ～♪", 10, 101011);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 91, 17614, "", "", 17614071, "", "", "", 0);
