INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 21314, 0.2, "", 21314063, "", "wac_birthday_talk_smile", 1, 110911);
