INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 30314, 0.2, "", 30314083, "", "wac_birthday_talk_sad", 1, 106411);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 30314, "", "", 30314084, 0, "vo_wac_30314_004", 0, "vo_wac_30314");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 30314, 0, 0.5, 30314085, 1, "そ、それはまた別の話でしょう！？\n私が言いたいのは……！", 10, 106411);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 91, 30314, "", "", 30314086, "", "", "", 0);
