INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 30314, 0.2, "", 30314088, "", "wac_birthday_talk_smile", 1, 105911);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 30314, "", "", 30314089, 0, "vo_wac_30314_005", 0, "vo_wac_30314");
