INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 31314, 0.2, "", 31314061, "", "wac_birthday_talk_smile", 1, 101511);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 31314, "", "", 31314062, 0, "vo_wac_31314_001", 0, "vo_wac_31314");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 31314, 0, 0.5, 31314063, 1, "うん、おめでとう～♪\nみんなでケーキも用意したから、\n楽しくお祝いしましょうね～\nほら、アオイちゃんも。", 10, 101511);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 91, 31314, "", "", 31314064, "", "", "", 0);
