INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 31314, 0.2, "", 31314071, "", "wac_birthday_talk_sad", 1, 101211);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 31314, "", "", 31314072, 0, "vo_wac_31314_003", 0, "vo_wac_31314");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 31314, 0, 0.5, 31314073, 1, "ヨーノモノ？　よく分かんないけど、\nとりあえずミサト先生も\nアオイちゃんもお祝いありがと～！\n……それとキミも！", 10, 101211);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 93, 31314, "", "", 31314074, "", 1, "", 4);
