INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 32314, 0.2, "", 32314066, "", "wac_birthday_talk_sad", 1, 105011);
