INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 38214, 0.2, "", 38214083, "", "wac_birthday_talk_smile", 1, 105211);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 38214, "", "", 38214084, 0, "vo_wac_38214_004", 0, "vo_wac_38214");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (1, 0, 11, 38214, 0, 0.5, 38214085, 1, "そうそう。\n難しい顔するより、\nみんなで楽しくおいしくケーキを\n食べましょう♪", 10, 105211);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 91, 38214, "", "", 38214086, "", "", "", 0);
