INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 3, 38214, 0.2, "", 38214088, "", "wac_birthday_talk_smile", 1, 103311);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES ("", "", 21, 38214, "", "", 38214089, 0, "vo_wac_38214_005", 0, "vo_wac_38214");
